def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find solid 3x3 colored blocks.
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[i][j] == color
                             for i in range(r, r + 3)
                             for j in range(c, c + 3)):
                center = (r + 1, c + 1, color)
                if center not in centers:
                    centers.append(center)

    # Extend each block's middle row and column across the grid.
    for r, c, color in centers:
        for j in range(w):
            out[r][j] = color
        for i in range(h):
            out[i][c] = color

    # Leave intersections of different blocks' lines empty.
    for r, c, color in centers:
        for rr, cc, other_color in centers:
            if color != other_color:
                out[r][cc] = 0
                out[rr][c] = 0

    return out
